/** Vsi liki (Marvel + DC). */
export const HEROES = [...MARVEL, ...DC];

/** Lik po id-ju. */
const BY_ID = new Map(HEROES.map(h => [h.id, h]));
export function heroById(id) { return BY_ID.get(id) || null; }

